from collections import deque


def assign_shifts(
    shifts: list[tuple[str, int, int, int]],
    engineers: dict[str, dict],
) -> dict[str, list[str]] | None:
    """Find an exact assignment using integral maximum flow."""
    result = {shift_id: [] for shift_id, _, _, _ in shifts}
    required = sum(headcount for _, _, headcount, _ in shifts)

    if required == 0:
        return result

    if sum(info["max_shifts"] for info in engineers.values()) < required:
        return None

    # Residual edges are stored in pairs; edge ^ 1 is the reverse edge.
    source, sink = 0, 1
    graph: list[list[int]] = [[], []]
    destinations: list[int] = []
    capacities: list[int] = []

    def new_node() -> int:
        graph.append([])
        return len(graph) - 1

    def add_edge(start: int, end: int, capacity: int) -> int:
        edge = len(destinations)
        destinations.extend((end, start))
        capacities.extend((capacity, 0))
        graph[start].append(edge)
        graph[end].append(edge ^ 1)
        return edge

    # Each shift has senior-only places and unrestricted places.
    # Filling every place enforces both headcount and the senior minimum.
    slots: dict[str, tuple[int, int | None, int | None]] = {}
    for shift_id, day, headcount, min_seniors in shifts:
        senior_node = None
        general_node = None

        if min_seniors:
            senior_node = new_node()
            add_edge(senior_node, sink, min_seniors)

        if headcount > min_seniors:
            general_node = new_node()
            add_edge(general_node, sink, headcount - min_seniors)

        slots[shift_id] = (day, senior_node, general_node)

    assignment_edges: list[tuple[int, str, str]] = []
    effective_capacity = 0

    for name, info in engineers.items():
        maximum = info["max_shifts"]
        if maximum == 0:
            continue

        engineer_node = new_node()
        day_nodes: dict[int, int] = {}
        is_senior = info["senior"]

        for shift_id in info["available"]:
            day, senior_node, general_node = slots[shift_id]

            if general_node is None and (
                not is_senior or senior_node is None
            ):
                continue

            day_node = day_nodes.get(day)
            if day_node is None:
                day_node = new_node()
                day_nodes[day] = day_node
                # At most one assignment for this engineer on this day.
                add_edge(engineer_node, day_node, 1)

            if is_senior and senior_node is not None:
                edge = add_edge(day_node, senior_node, 1)
                assignment_edges.append((edge, name, shift_id))

            if general_node is not None:
                edge = add_edge(day_node, general_node, 1)
                assignment_edges.append((edge, name, shift_id))

        capacity = min(maximum, len(day_nodes))
        if capacity:
            add_edge(source, engineer_node, capacity)
            effective_capacity += capacity

    if effective_capacity < required:
        return None

    # Dinic's algorithm, with iterative path searches to avoid recursion limits.
    flow = 0
    node_count = len(graph)

    while flow < required:
        level = [-1] * node_count
        level[source] = 0
        queue = deque([source])

        while queue:
            node = queue.popleft()
            next_level = level[node] + 1
            for edge in graph[node]:
                neighbor = destinations[edge]
                if capacities[edge] > 0 and level[neighbor] == -1:
                    level[neighbor] = next_level
                    queue.append(neighbor)

        if level[sink] == -1:
            return None

        current = [0] * node_count

        while flow < required:
            nodes = [source]
            path: list[int] = []

            while nodes:
                node = nodes[-1]
                if node == sink:
                    break

                edges = graph[node]
                position = current[node]

                while position < len(edges):
                    edge = edges[position]
                    if (
                        capacities[edge] > 0
                        and level[destinations[edge]] == level[node] + 1
                    ):
                        break
                    position += 1

                current[node] = position

                if position == len(edges):
                    # No remaining admissible path from this node.
                    level[node] = -1
                    nodes.pop()
                    if path:
                        path.pop()
                        current[nodes[-1]] += 1
                else:
                    edge = edges[position]
                    path.append(edge)
                    nodes.append(destinations[edge])

            if not nodes:
                break

            amount = required - flow
            for edge in path:
                amount = min(amount, capacities[edge])

            for edge in path:
                capacities[edge] -= amount
                capacities[edge ^ 1] += amount

            flow += amount

    for edge, name, shift_id in assignment_edges:
        if capacities[edge] == 0:
            result[shift_id].append(name)

    return result
